	gUnit = GetFilterUnit()
	local o = GetUnitCurrentOrder(gUnit)
	if UnitAlive(gUnit) and IsUnitInGroup(gUnit, udg_Ai_navy[GetPlayerId(CheckPlayer)]) and (o == 851972 or o == 851976 or o == 0) then
		LazyCount = LazyCount + 1
		return true
	else
		return false
	end
end
