-- *  AddExp
---@param u unit
---@param pi integer
---@return nothing
function addArmyExp(u, pi)
	--    call BJDebugMsg("Start")
	gPlayer = GetOwningPlayer(u)
	gId = GetUnitTypeId(u)
	gPi = GetPlayerId(gPlayer)
	if IsPlayerAlly(gPlayer, Player(pi)) then
		return 
	end
	
	if IsUnitType(u, UNIT_TYPE_STRUCTURE) then
		if IsUnitInGroup(gAttacked, udg_ZahvatBuildings) then
			gReal = 1
		else
			gReal = (I2R(GetUnitGoldCost(gId)) * 0.01)
		end
	else
		if IsUnitType(u, UNIT_TYPE_HERO) then
			gReal = (GetHeroLevel(u) * 1)
		else
			gReal = (I2R(GetUnitGoldCost(gId)) * 0.02)
		end
	end
	ArmyExp[pi] = ArmyExp[pi] + gReal
	ArmyExp[gPi] = RMaxBJ(0, ArmyExp[gPi] - gReal * 0.9)
	--  call BJDebugMsg( GetUnitName(u)+" "+R2S(ArmyExp[pi]))
end
-- Устанавливает бонус за опыт
---@param pi integer
---@return nothing
function ArmyExpSetBonus(pi)
	if ArmyExpBonus[pi] == nil then
		return
	end
	SetUnitAbilityLevel(ArmyExpBonus[pi], FourCC('arb1'), IMinBJ(R2I((ArmyExp[pi] / 500) + 1), 11))
	SetUnitAbilityLevel(ArmyExpBonus[pi], FourCC('arb0'), IMinBJ(R2I((ArmyExp[pi] / 500) + 1), 11))
end
--  Добавляет столбец опыта
---@return nothing
function ExpandTableArmyExpr()
	local i = 0
	local l__max = 1
	MultiboardSetColumnCount(Multiboard, 4)
	
	
	ArmyPowerColumn[24] = MultiboardGetItem(Multiboard, 0, 3)
	MultiboardSetItemValue(ArmyPowerColumn[24], "Опыт")
	MultiboardSetItemWidth(ArmyPowerColumn[24], 0.06)
	MultiboardReleaseItem(ArmyPowerColumn[24])
	
	while true do
		if i > 23 then break end
		ArmyExp[i] = 0.001
		if GetPlayerSlotState(Player(i)) == PLAYER_SLOT_STATE_PLAYING or IsPlayerInForce(Player(i), udg_Bots) then
			ArmyPowerColumn[i] = MultiboardGetItem(Multiboard, l__max, 3)
			MultiboardSetItemValue(ArmyPowerColumn[i], "0")
			MultiboardSetItemWidth(ArmyPowerColumn[i], 0.06)
			l__max = l__max + 1
		end
		i = i + 1
		
	end
	
	
	
	MultiboardDisplay(Multiboard, false)
	MultiboardDisplay(Multiboard, true)
	
	
end
-- ***************************************************************************
-- *  UpdateGraph
---@param pi integer
---@return nothing
function PercentGraph(pi)
	if ThirdColumn[pi] == nil and EnsureMultiboardPlayerRow(pi) == nil then
		return
	end
	MultiboardSetItemValue(ThirdColumn[pi], (R2SW_Polyfill(I2R(CityPlayerCount[pi]) * 100.0 / I2R(CityCount)) .. "%"))
end
---@param pi integer
---@return nothing
function ArmyExpGraph(pi)
	if ArmyPowerColumn[pi] == nil and EnsureMultiboardPlayerRow(pi) == nil then
		return
	end
	MultiboardSetItemValue(ArmyPowerColumn[pi], R2SW_Polyfill(ArmyExp[pi]))
end
---@param pi integer
---@return nothing
function UpdateGraf(pi)
	local p = Player(pi)
	local ownerIndex = EnsureMultiboardPlayerRow(pi)
	local r = R2I(udg_UnitsCount[pi] / 25.00)
	logistic[pi] = ((500 + 100 * (r - 1)) / 2 * r)	--  прогрессия
	
	-- Общий модификатор расходов
	if GetPlayerTechCount(p, FourCC('R0DV'), true) + GetPlayerTechCount(p, FourCC('R0GZ'), true) >= 1 then
		additional[pi] = disincome[pi] * (udg_MainPrice[pi] / (-100.0))
	end
	
	
	if DisOn then
		balance[pi] = income[pi] - disincome[pi] + corruption[pi] - logistic[pi] + additional[pi]
	else
		balance[pi] = income[pi]
	end
	
	--  Табличка
	if ownerIndex == nil then
		return
	end
	MultiboardSetItemValue(MultiboardItem[ownerIndex * 2 + 1], I2S(udg_UnitsCount[pi]))
	PercentGraph(pi)
	ArmyExpGraph(pi)
	
end
