---@param u unit
---@return nothing
function Enter(u)
	local id = GetUnitTypeId(u)
	local p = GetOwningPlayer(u)
	local pi = GetPlayerId(p)
	local ownerIndex = EnsureMultiboardPlayerRow(pi)
	
	
	
	if ownerIndex == nil then
		return
	end
	MultiboardSetItemValue(MultiboardItem[ownerIndex * 2 + 1], I2S(udg_UnitsCount[pi]))
	
	
end
-- ***************************************************************************
-- *  Settings
---@return nothing
function StartInc()
	
	local i = 0
	while true do
		if i >= 24 then break end
		income[i] = 0
		incomeW[i] = 0
		disincome[i] = 0
		logistic[i] = 0
		corruption[i] = 0
		balance[i] = 0
		additional[i] = 0
		AllyTax[i] = 0
		i = i + 1
	end
	RegionAddRect(Allmap, GetWorldBounds())
	
end
-- ***************************************************************************
-- *  CountAddDis and CountDelDis
---@param u unit
---@param pi integer
---@return nothing
function AddCountDis(u, pi)
	local i
	-- Добавляет потребление с юнита    
	
	if u == nil then
		return 
	end
	
	--  Кейс здания или его симуляция
	if (IsUnitType(u, UNIT_TYPE_STRUCTURE) or GetUnitAbilityLevel(u, FourCC('A1IJ')) > 0) then
		if IsUnitInGroup(u, udg_BuildedSctructure[1]) then
			income[pi] = income[pi] + I2R(GetUnitFoodMade(u))
			
			-- Различные дополнения 
			if GetUnitAbilityLevel(u, FourCC('A0AY')) >= 1 then
				income[pi] = (income[pi] + (100.00 * I2R(GetUnitAbilityLevel(u, FourCC('A0AY')))))
			elseif GetUnitAbilityLevel(u, FourCC('A0SM')) >= 1 then
				income[pi] = (income[pi] + (75.00 * I2R(GetUnitAbilityLevel(u, FourCC('A0SM')))))
			elseif GetUnitAbilityLevel(u, FourCC('A0VS')) == 1 then
				income[pi] = (income[pi] + 100)
			end
			
			if GetUnitAbilityLevel(u, FourCC('A1HS')) > 0 then
				income[pi] = (income[pi] - 5)
				i = LoadInteger(Hash, GetHandleId(u), 0)
				income[i] = (income[i] + 5)
			end
			
			
			i = GetUnitAbilityLevel(u, FourCC('A0B5'))
			if i > 0 then
				incomeW[pi] = incomeW[pi] + (50.00 * i)
			end
		end
		
		--  Кейс юнита
	else
		-- Это не оживление мертвых, не суммон
		if  not IsUnitType(u, UNIT_TYPE_SUMMONED) then
			
			udg_UnitsCount[pi] = udg_UnitsCount[pi] + 1
			-- call DisplayTextToPlayer(p,0,0,I2S(udg_UnitsCount[pi]))
			
			
			if IsUnitType(u, UNIT_TYPE_HERO) then
				disincome[pi] = (disincome[pi] + 100.00)
				if GetUnitAbilityLevel(u, FourCC('A0XV')) ~= 0 then	--  Казначейская аблика
					income[pi] = income[pi] + (100 + GetUnitAbilityLevel(u, FourCC('A0XV')) * 100)
				end
				
			else
				udg_Price = GetUnitGoldCost(GetUnitTypeId(u)) or 0
				disincome[pi] = (disincome[pi] + (udg_Price * Tax))
				--  ---------------------------Особые условия-----------------------------          +++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
				--  ---------------------------Топливо гоблинов-----------------------------
				if GetUnitAbilityLevel(u, FourCC('A0A5')) ~= 0 then
					disincome[pi] = disincome[pi] + ((udg_Price * Tax) * (1.60 - (0.10 * I2R(GetUnitAbilityLevel(u, FourCC('A0A5'))))))
					
					--  ---------------------------Поколения Силитидов-------------------------
				elseif GetUnitAbilityLevel(u, FourCC('A0VH')) == 1 then
					disincome[pi] = disincome[pi] - (udg_Price * Tax / 2)
				elseif GetUnitAbilityLevel(u, FourCC('A0VH')) == 2 then
					disincome[pi] = disincome[pi] - (udg_Price * Tax / 3 * 2)
					
					-- Horde land
					--    elseif  GetUnitAbilityLevel(u,'OR00')!=0 then
					
					--   set disincome[pi] = disincome[pi] + ( ( udg_Price * Tax ) * ( ( GetUnitAbilityLevel(u,'OR00')-35 )/100.0) )
					
				end
				
				
			end
			
			
			-- Случай призывных у культа.
		elseif GetUnitAbilityLevel(u, FourCC('A1HL')) > 0 then
			udg_UnitsCount[pi] = udg_UnitsCount[pi] + 1
			udg_Price = GetUnitGoldCost(GetUnitTypeId(u)) or 0
			disincome[pi] = (disincome[pi] + (udg_Price * Tax / 2))
		end
		
	end
	
	
	
	
	UpdateGraf(pi)
	
end
---@param u unit
---@param pi integer
---@return nothing
function DelCountDis(u, pi)
	local i
	-- Убирает потребление с юнита
	
	if u == nil then
		return 
	end
	
	
	-- юнит
	-- Здание
	if (IsUnitType(u, UNIT_TYPE_STRUCTURE) or GetUnitAbilityLevel(u, FourCC('A1IJ')) > 0) then
		
		if IsUnitInGroup(u, udg_BuildedSctructure[1]) then
			income[pi] = income[pi] - I2R(GetUnitFoodMade(u))
			
			-- Различные дополнения
			if GetUnitAbilityLevel(u, FourCC('A0AY')) >= 1 then
				income[pi] = (income[pi] - (100.00 * I2R(GetUnitAbilityLevel(u, FourCC('A0AY')))))
			elseif GetUnitAbilityLevel(u, FourCC('A0SM')) >= 1 then
				income[pi] = (income[pi] - (75.00 * I2R(GetUnitAbilityLevel(u, FourCC('A0SM')))))
			end
			
			if GetUnitAbilityLevel(u, FourCC('A0VS')) == 1 then
				income[pi] = (income[pi] - 100)
			end
			
			if GetUnitAbilityLevel(u, FourCC('A1HS')) > 0 then
				income[pi] = (income[pi] + 5)
				i = LoadInteger(Hash, GetHandleId(u), 0)
				income[i] = (income[i] - 5)
				FlushChildHashtable(Hash, GetHandleId(u))
			end
			
			
			
			i = GetUnitAbilityLevel(u, FourCC('A0B5'))
			if i > 0 then
				incomeW[pi] = incomeW[pi] - (50.00 * i)
			end
		end
		
		-- Не здание
		-- Это не оживление мертвых, не суммон
	elseif  not IsUnitType(u, UNIT_TYPE_SUMMONED) then
		udg_UnitsCount[pi] = udg_UnitsCount[pi] - 1
		-- Гер
		if IsUnitType(u, UNIT_TYPE_HERO) then
			disincome[pi] = (disincome[pi] - 100.00)
			
			
			-- Различные дополнения
			if GetUnitAbilityLevel(u, FourCC('A0XV')) ~= 0 then
				income[pi] = income[pi] - (100 + GetUnitAbilityLevel(u, FourCC('A0XV')) * 100)
			end
			
			-- юнит
		else
			
			
			--  call DisplayTextToPlayer(p,0,0,("Увидел смерть до юнита "+GetUnitName(u)))
			udg_Price = GetUnitGoldCost(GetUnitTypeId(u)) or 0
			disincome[pi] = (disincome[pi] - (udg_Price * Tax))
			
			
			-- Различные дополнения
			--  ---------------------------Топливо гоблинов-----------------------------
			if GetUnitAbilityLevel(u, FourCC('A0A5')) ~= 0 then
				disincome[pi] = disincome[pi] - ((udg_Price * Tax) * (1.60 - (0.10 * I2R(GetUnitAbilityLevel(u, FourCC('A0A5'))))))
				
				--  ---------------------------Поколения Силитидов------------------------- ??
			elseif GetUnitAbilityLevel(u, FourCC('A0VH')) == 1 then
				disincome[pi] = disincome[pi] + (udg_Price * Tax / 2)
			elseif GetUnitAbilityLevel(u, FourCC('A0VH')) == 2 then
				disincome[pi] = disincome[pi] + (udg_Price * Tax / 3 * 2)
			elseif GetUnitAbilityLevel(u, FourCC('OR00')) ~= 0 then
				disincome[pi] = disincome[pi] - ((udg_Price * Tax) * ((GetUnitAbilityLevel(u, FourCC('OR00')) - 35) / 100.0))
				
				-- Horde land
				--  elseif  GetUnitAbilityLevel(u,'OR00')!=0 then                  
				--     set disincome[pi] = disincome[pi] - ( ( udg_Price * Tax ) * ( ( GetUnitAbilityLevel(u,'OR00')-35 )/100.0) )
				
			end
		end
		
		
		
		
		-- Случай призывных у культа.
	elseif GetUnitAbilityLevel(u, FourCC('A1HL')) > 0 then
		udg_UnitsCount[pi] = udg_UnitsCount[pi] - 1
		udg_Price = GetUnitGoldCost(GetUnitTypeId(u)) or 0
		disincome[pi] = (disincome[pi] - (udg_Price * Tax / 2))
		
	end
	
	UpdateGraf(pi)
	u = nil
end
---@return nothing
function TimedCountAct()
	local t = GetExpiredTimer()
	local tid = GetHandleId(t)
	local u = LoadUnitHandle(Hash, tid, 1)
	DelCountDis(u, GetPlayerId(GetOwningPlayer(u)))
	
	FlushChildHashtable(Hash, tid)
	DestroyTimer(t)
	t = nil
	u = nil
end
---@param u unit
---@return nothing
function TimedCount(u)
	local t = CreateTimer()
	SaveUnitHandle(Hash, GetHandleId(t), 1, u)
	TimerStart(t, 0.3, false, TimedCountAct)
	
	t = nil
end
-- ***************************************************************************
-- *  ClearEc
---@param pi integer
---@return nothing
function ClearEc(pi)
	income[pi] = 0
	incomeW[pi] = 0
	disincome[pi] = 0
	logistic[pi] = 0
	corruption[pi] = 0
	balance[pi] = 0
	additional[pi] = 0
	udg_UnitsCount[pi] = 0
	CityPlayerCount[pi] = 0
end
-- call ClearEc(GetPlayerId(GetEnumPlayer()))
-- ***************************************************************************
-- *  ClearPlayer
---@return nothing
function KillAll()
	local u = GetEnumUnit()
	local id = GetUnitTypeId(u)
	local p = GetOwningPlayer(u)
	if IsUnitInGroup(u, udg_ZahvatBuildings) or GetUnitAbilityLevel(u, FourCC('A1HJ')) > 0 then
		SetUnitOwner(u, Player(25), true)
	elseif IsUnitInGroup(u, udg_StolicaGroups) then
		RemoveUnit(u)
	else
		-- Случай пилота танка
		if id == FourCC('h0KS') then
			UnitRemoveAbility(u, FourCC('A18O'))
		end
		if IsUnitType(u, UNIT_TYPE_HERO) then
			SetPlayerTechMaxAllowed(p, id, GetPlayerTechMaxAllowed(p, id) + 1)
		end
		RemoveUnit(u)
	end
	
	u = nil
	p = nil
end
---@param p player
---@return nothing
function ClearPlayer(p)
	local pi = GetPlayerId(p)
	local g = CreateGroup()
	
	GroupEnumUnitsOfPlayer(g, p, nil)
	ForGroup(g, KillAll)
	GroupClear(g)
	SetPlayerStateBJ(Player(pi), PLAYER_STATE_RESOURCE_GOLD, 0)
	SetPlayerStateBJ(Player(pi), PLAYER_STATE_RESOURCE_LUMBER, 0)
	
	SetPlayerAbilityAvailable(Player(pi), FourCC('A0IQ'), true)
	ClearEc(pi)
	turnOffAi(pi)
	UpdateGraf(pi)
	playerCapital[pi] = nil
	ArmyExp[pi] = 0.0
	
	
	DestroyGroup(g)
	g = nil
end
-- ***************************************************************************
-- *  TimedUpdate
---@return nothing
function TimedUpdateCheck()
	local t = GetExpiredTimer()
	local id = GetHandleId(t)
	local u = LoadUnitHandle(Hash, id, 1)
	local p = LoadPlayerHandle(Hash, id, 2)
	local currentLevel = LoadInteger(Hash, id, 3)
	
	
	
	local levels = 4
	local pi = GetPlayerId(p)
	
	if GetUnitAbilityLevel(GetTriggerUnit(), FourCC('A1N9')) > 0 then
		levels = levels - 2
	end
	
	
	if GetOwningPlayer(u) == p and UnitAlive(u) and currentLevel <= levels then
		
		-- Development
		BlzStartUnitAbilityCooldown(u, FourCC('A10G'), 300)
		-- call BlzSetUnitAbilityCooldown(u,'A10G',1,300)
		
		-- Golda
		if GetUnitAbilityLevel(u, FourCC('A0AY')) == 0 then
			UnitAddAbility(u, FourCC('A0AY'))
			income[pi] = income[pi] + 100
			
			
		elseif GetUnitAbilityLevel(u, FourCC('A0AY')) < levels then
			income[pi] = income[pi] + 100
			IncUnitAbilityLevel(u, FourCC('A0AY'))
			
		else	-- if GetUnitAbilityLevel(u, FourCC('A0AY')) >= levels then
			income[pi] = income[pi] + 100
			UnitRemoveAbility(u, FourCC('A0AZ'))
			
			
		end
		
		-- Lumber
		if GetUnitAbilityLevel(u, FourCC('A0B5')) == 0 then
			UnitAddAbility(u, FourCC('A0B5'))
			incomeW[pi] = incomeW[pi] + 50.00
		elseif GetUnitAbilityLevel(u, FourCC('A0B5')) < levels then
			IncUnitAbilityLevel(u, FourCC('A0B5'))
			incomeW[pi] = incomeW[pi] + 50.00
		else	-- if GetUnitAbilityLevel( u,FourCC('A0B5') ) >= levels then
			UnitRemoveAbility(u, FourCC('A0B1'))
			
		end
		
		if GetUnitAbilityLevel(u, FourCC('A0AY')) + GetUnitAbilityLevel(u, FourCC('A0B5')) >= levels * 2 then
			-- Развитие
			BlzUnitHideAbility(u, FourCC('A10G'), true)
			BlzUnitDisableAbility(u, FourCC('A10G'), true, true)
			
			
		end
		
		UpdateGraf(pi)
		u = nil
		p = nil
		SaveInteger(Hash, id, 3, currentLevel + 1)
		TimerStart(t, 300, false, TimedUpdateCheck)
		t = nil
		
	else
		u = nil
		p = nil
		DestroyTimer(t)
		t = nil
		FlushChildHashtable(Hash, id)
	end
end
---@param u unit
---@param p player
---@return nothing
function TimedUpdate(u, p)
	local t = CreateTimer()
	local id = GetHandleId(t)
	
	UnitAddAbility(u, FourCC('A10G'))
	BlzStartUnitAbilityCooldown(u, FourCC('A10G'), 300)
	TimerStart(t, 300, false, TimedUpdateCheck)
	SaveUnitHandle(Hash, id, 1, u)
	SavePlayerHandle(Hash, id, 2, p)
	SaveInteger(Hash, id, 3, 1)
	
	u = nil
	p = nil
	t = nil
	
	
end
