---@param x real
---@param y real
---@param g group
---@return nothing
function ProcessContinentalStuff(x, y, g)
	if HandleKalim(x, y, g) then
	elseif HandleVK(x, y, g) then
	elseif HandleNord(x, y, g) then
	elseif HandlePandaria(x, y, g) then
	elseif HandleOutland(x, y, g) then
	elseif HandleBrokenIsles(x, y, g) then
	elseif HandleArgus(x, y, g) then
	elseif HandleWestDungeons(x, y, g) then
	elseif HandleCentralDungeons(x, y, g) then
	end
	
	RemWaterPortals(g)
	RemEmeraldPortals(g)
end
--  НАГИ особое расположение
---@param x real
---@param y real
---@param g group
---@return nothing
function ProcessContinentalStuffNaga(x, y, g)
	
	if HandleOutland(x, y, g) then
	elseif HandleArgus(x, y, g) then
	elseif HandleAnkirag(x, y, g) then
	elseif HandleWestDungeons(x, y, g) then
	elseif HandleCentralDungeons(x, y, g) then
	end
	
	
	RemWaterPortals(g)
	RemEmeraldPortals(g)
end
-- ***************************************************************************
-- *  TryToAttack2 Uni
---@param u unit
---@param l__gEnemyGroup group
---@param l__gX real
---@param l__gY real
---@param i integer
---@return nothing
function TryPortalMovement(u, l__gEnemyGroup, l__gX, l__gY, i)
	local abilityLevel = GetUnitAbilityLevel(u, FourCC('A1GZ'))
	if i == 0 then
		i = 20
	end
	
	Counter = 0
	EnemyCapital = nil
	-- Еще осталось 1 попатка тепнуться
	if abilityLevel == 1 then
		GroupEnumUnitsInRange(l__gEnemyGroup, l__gX, l__gY, 3000.00 * (Pow(1.5, I2R(i))), udg_B_EnemyUnitP)
		-- Порталы запрещены
	elseif abilityLevel >= 2 then
		GroupEnumUnitsInRange(l__gEnemyGroup, l__gX, l__gY, 3000.00 * (Pow(1.5, I2R(i))), udg_B_EnemyUnit)
		UnitRemoveAbility(u, FourCC('A1GZ'))
		-- Обычный поиск
	else
		GroupEnumUnitsInRange(l__gEnemyGroup, l__gX, l__gY, 3000.00 * (Pow(1.5, I2R(i))), udg_B_EnemyUnitP)
	end
	
end
---@return nothing
function TryAttack()
	local i
	gUnit = udg_LocalUnit2
	gPlayer = GetOwningPlayer(gUnit)
	local pi_attack = GetPlayerId(gPlayer)
	gX = GetUnitX(gUnit)
	gY = GetUnitY(gUnit)
	--    ------------------- В атаку -------------------
	
	if gAllyGroup == nil then
		gAllyGroup = CreateGroup()
	end
	if gSubGroup == nil then
		gSubGroup = CreateGroup()
	end
	
	CheckPlayer = gPlayer
	-- // Дальнее исследование
	if Random(1, 8) then
		
		-- Обработка портала и вообще выбор врагов
		TryPortalMovement(gUnit, gEnemyGroup, gX, gY, 0)
		
		-- /Континентальные штуки
		if AiRace[GetPlayerId(gPlayer)] == "Naga" then
			ProcessContinentalStuffNaga(gX, gY, gEnemyGroup)
		else
			ProcessContinentalStuff(gX, gY, gEnemyGroup)
		end
		
		
		
		--  Шанс напасать именно на столицу
		if EnemyCapital ~= nil and Random(1, 2) then
			gEnemy = EnemyCapital
		else
			if Counter > 0 then
				gEnemy = BlzGroupUnitAt(gEnemyGroup, GetRandomInt(0, Counter - 1))
			else
				gEnemy = nil
				AiProbeLogLimited(pi_attack, "Log_TryAttack_NoEnemyFast", 8, "[AIARMY] no-enemy pi=" .. tostring(pi_attack) .. " mode=fast seekerId=" .. tostring(GetUnitTypeId(gUnit)))
			end
		end
		
		-- Враг не найден - запрашиваем тп!
		if gEnemy == nil then
			AiProbeLogLimited(pi_attack, "Log_TryAttack_RequestPortFast", 8, "[AIARMY] request-port pi=" .. tostring(pi_attack) .. " mode=fast seekerId=" .. tostring(GetUnitTypeId(gUnit)))
			RequestPort(gUnit)
		else
			
			gX2 = GetUnitX(gEnemy)
			gY2 = GetUnitY(gEnemy)
			
			--  Если это портал
			if WaygateIsActive(gEnemy) == true then
				
				gDx = gX - gX2
				gDy = gY - gY2
				gDx = SquareRoot(gDx * gDx + gDy * gDy)
				GroupEnumUnitsInRange(gAllyGroup, gX, gY, 2500 * AiRadius / 5, B_LazyF)
				local allyCount = CountUnitsInGroup(gAllyGroup)
				
				
				-- В любом случае спелы проверки портала получат
				
				while true do
					gUnit2 = FirstOfGroup(gAllyGroup)
					if gUnit2 == nil then break end
					UnitAddAbility(gUnit2, FourCC('A1GZ'))
					GroupRemoveUnit(gAllyGroup, gUnit2)
					gUnit2 = nil
				end
				-- До портала всего нечего
				if gDx <= 2500 then
					
					IssueImmediateOrder(gEnemy, "web")
					BlzEndUnitAbilityCooldown(gEnemy, FourCC('A0HY'))
					
					-- До портала идти еще
				else
					local attackLogCount = LoadInteger(AiData, pi_attack, StringHash("Log_TryAttackOrderCount"))
					if allyCount == 0 then
						AiProbeLogLimited(pi_attack, "Log_TryAttack_NoPortalAlliesFast", 8, "[AIARMY] no-allies pi=" .. tostring(pi_attack) .. " mode=portal-fast targetId=" .. tostring(GetUnitTypeId(gEnemy)))
					end
					if attackLogCount < 10 then
						SaveInteger(AiData, pi_attack, StringHash("Log_TryAttackOrderCount"), attackLogCount + 1)
						ProbeLogWrite("[AIARMY] attack-order pi=" .. tostring(pi_attack) .. " via=portal targetId=" .. tostring(GetUnitTypeId(gEnemy)) .. " allies=" .. tostring(allyCount) .. " x=" .. tostring(gX2) .. " y=" .. tostring(gY2))
					end
					GroupPointOrder(gAllyGroup, "smart", gX2, gY2)
					
				end
				
				
				
				
				--  Основной случай
			else
				-- set CheckPlayer = gPlayer
				GroupEnumUnitsInRange(gAllyGroup, gX, gY, 1500 * AiRadius / 5, B_LazyF)
				local allyCount = CountUnitsInGroup(gAllyGroup)
				if allyCount == 0 then
					AiProbeLogLimited(pi_attack, "Log_TryAttack_NoGroupAlliesFast", 8, "[AIARMY] no-allies pi=" .. tostring(pi_attack) .. " mode=group-fast targetId=" .. tostring(GetUnitTypeId(gEnemy)))
				end
				gSubGroupCounter = 0
				GroupClear(gSubGroup)
				while true do
					gUnit2 = FirstOfGroup(gAllyGroup)
					
					if gUnit2 == nil then
						local attackLogCount = LoadInteger(AiData, pi_attack, StringHash("Log_TryAttackOrderCount"))
						if attackLogCount < 10 then
							SaveInteger(AiData, pi_attack, StringHash("Log_TryAttackOrderCount"), attackLogCount + 1)
							ProbeLogWrite("[AIARMY] attack-order pi=" .. tostring(pi_attack) .. " via=group targetId=" .. tostring(GetUnitTypeId(gEnemy)) .. " allies=" .. tostring(allyCount) .. " x=" .. tostring(gX2) .. " y=" .. tostring(gY2))
						end
						GroupPointOrder(gSubGroup, "attack", gX2, gY2)
						GroupClear(gSubGroup)
						gSubGroupCounter = 0
						if true then break end
					end
					GroupRemoveUnit(gAllyGroup, gUnit2)
					
					
					GroupAddUnit(gSubGroup, gUnit2)
					gSubGroupCounter = gSubGroupCounter + 1
					if gSubGroupCounter >= 12 then
						GroupPointOrder(gSubGroup, "attack", gX2, gY2)
						GroupClear(gSubGroup)
						gSubGroupCounter = 0
					end
					
					--  Сломался с неуязом
					if GetUnitAbilityLevel(gUnit2, FourCC('Bvul')) > 0 then
						ReplaceUnit2(gUnit2, GetUnitTypeId(gUnit2), bj_UNIT_STATE_METHOD_RELATIVE)
					end
					
					gUnit2 = nil
				end
			end
		end
		
		
		-- // Ближайшее исследование, пытается перебрадть радиус пока не найдет хотя бы одного юнита
	else
		
		
		i = 0
		while true do
			if i > 8 then break end
			i = i + 1
			if i == 8 then
				i = 100
			end
			
			
			-- set CheckPlayer = gPlayer
			
			TryPortalMovement(gUnit, gEnemyGroup, gX, gY, i)
			
			-- /Континентальные штуки
			if AiRace[GetPlayerId(gPlayer)] == "Naga" then
				ProcessContinentalStuffNaga(gX, gY, gEnemyGroup)
			else
				ProcessContinentalStuff(gX, gY, gEnemyGroup)
			end
			
			
			--  Шанс напасать именно на столицу
			if EnemyCapital ~= nil and Random(1, 4) then
				gEnemy = EnemyCapital
			else
				if Counter > 0 then
					gEnemy = BlzGroupUnitAt(gEnemyGroup, GetRandomInt(0, Counter - 1))
				else
					gEnemy = nil
					AiProbeLogLimited(pi_attack, "Log_TryAttack_NoEnemyWide", 8, "[AIARMY] no-enemy pi=" .. tostring(pi_attack) .. " mode=wide seekerId=" .. tostring(GetUnitTypeId(gUnit)) .. " pass=" .. tostring(i))
				end
			end
			
			-- Враг не найден - запрашиваем тп!
			if gEnemy == nil then
				if i == 100 then
					AiProbeLogLimited(pi_attack, "Log_TryAttack_RequestPortWide", 8, "[AIARMY] request-port pi=" .. tostring(pi_attack) .. " mode=wide seekerId=" .. tostring(GetUnitTypeId(gUnit)))
					RequestPort(gUnit)
				end
				-- Враг найден
			else
				i = 15
				gX2 = GetUnitX(gEnemy)
				gY2 = GetUnitY(gEnemy)
				
				if WaygateIsActive(gEnemy) then
					
					gDx = gX - gX2
					gDy = gY - gY2
					gDx = SquareRoot(gDx * gDx + gDy * gDy)
					GroupEnumUnitsInRange(gAllyGroup, gX, gY, 2500 * AiRadius / 5, B_LazyF)
					local allyCount = CountUnitsInGroup(gAllyGroup)
					
					
					-- В любом случае спелы проверки портала получат
					
					while true do
						gUnit2 = FirstOfGroup(gAllyGroup)
						if gUnit2 == nil then break end
						UnitAddAbility(gUnit2, FourCC('A1GZ'))
						GroupRemoveUnit(gAllyGroup, gUnit2)
						gUnit2 = nil
					end
					-- До портала всего ничего
					if gDx <= 2500 then
						AiProbeLogLimited(pi_attack, "Log_TryAttack_PortalNearby", 8, "[AIARMY] portal-near pi=" .. tostring(pi_attack) .. " targetId=" .. tostring(GetUnitTypeId(gEnemy)) .. " allies=" .. tostring(allyCount))
						
						IssueImmediateOrder(gEnemy, "web")
						BlzEndUnitAbilityCooldown(gEnemy, FourCC('A0HY'))
						
					-- До портала идти еще
					else
						if allyCount == 0 then
							AiProbeLogLimited(pi_attack, "Log_TryAttack_NoPortalAlliesWide", 8, "[AIARMY] no-allies pi=" .. tostring(pi_attack) .. " mode=portal-wide targetId=" .. tostring(GetUnitTypeId(gEnemy)))
						end
						local attackLogCount = LoadInteger(AiData, pi_attack, StringHash("Log_TryAttackOrderCount"))
						if attackLogCount < 10 then
							SaveInteger(AiData, pi_attack, StringHash("Log_TryAttackOrderCount"), attackLogCount + 1)
							ProbeLogWrite("[AIARMY] attack-order pi=" .. tostring(pi_attack) .. " via=portal-wide targetId=" .. tostring(GetUnitTypeId(gEnemy)) .. " allies=" .. tostring(allyCount) .. " x=" .. tostring(gX2) .. " y=" .. tostring(gY2))
						end
						GroupPointOrder(gAllyGroup, "smart", gX2, gY2)
						
					end
					
					-- Обычная цель
				else
					
					-- Отдаю приказ юниту и рядом стоящим
					
					-- set CheckPlayer = gPlayer
					GroupEnumUnitsInRange(gAllyGroup, gX, gY, 1500 * AiRadius / 5, B_LazyF)
					local allyCount = CountUnitsInGroup(gAllyGroup)
					if allyCount == 0 then
						AiProbeLogLimited(pi_attack, "Log_TryAttack_NoGroupAlliesWide", 8, "[AIARMY] no-allies pi=" .. tostring(pi_attack) .. " mode=group-wide targetId=" .. tostring(GetUnitTypeId(gEnemy)))
					end
					gSubGroupCounter = 0
					GroupClear(gSubGroup)
					while true do
						gUnit2 = FirstOfGroup(gAllyGroup)
						
						if gUnit2 == nil then
							local attackLogCount = LoadInteger(AiData, pi_attack, StringHash("Log_TryAttackOrderCount"))
							if attackLogCount < 10 then
								SaveInteger(AiData, pi_attack, StringHash("Log_TryAttackOrderCount"), attackLogCount + 1)
								ProbeLogWrite("[AIARMY] attack-order pi=" .. tostring(pi_attack) .. " via=group-wide targetId=" .. tostring(GetUnitTypeId(gEnemy)) .. " allies=" .. tostring(allyCount) .. " x=" .. tostring(gX2) .. " y=" .. tostring(gY2))
							end
							GroupPointOrder(gSubGroup, "attack", gX2, gY2)
							GroupClear(gSubGroup)
							gSubGroupCounter = 0
							if true then break end
						end
						GroupRemoveUnit(gAllyGroup, gUnit2)
						
						
						GroupAddUnit(gSubGroup, gUnit2)
						gSubGroupCounter = gSubGroupCounter + 1
						if gSubGroupCounter >= 12 then
							GroupPointOrder(gSubGroup, "attack", gX2, gY2)
							GroupClear(gSubGroup)
							gSubGroupCounter = 0
						end
						
						--  Сломался с неуязом
						if GetUnitAbilityLevel(gUnit2, FourCC('Bvul')) > 0 then
							ReplaceUnit2(gUnit2, GetUnitTypeId(gUnit2), bj_UNIT_STATE_METHOD_RELATIVE)
						end
						
						gUnit2 = nil
					end
					
					
					
				end
				
				
			end
			
		end
		
		UnitRemoveAbility(gUnit, FourCC('A1GZ'))
		
	end
	
end
-- ***************************************************************************
-- *  TryToAttackN Uni
---@return nothing
function TryAttackN()
	local ChosenUnit = udg_LocalUnit3
	local u2
	local x = GetUnitX(ChosenUnit)
	local y = GetUnitY(ChosenUnit)
	local x2
	local y2
	
	
	--  Шанс на дальнее исследование
	if Random(1, 10) then
		gInt = 10
	else
		gInt = 1
	end
	
	
	while true do
		
		-- call BJDebugMsg("Цикл атаки флота юнита: "+GetUnitName(ChosenUnit)+" Игрока:"+GetPlayerName(CheckPlayer))
		-- Блок выбора врагов
		
		Counter = 0
		CheckPlayer = GetOwningPlayer(ChosenUnit)
		GroupEnumUnitsInRange(gEnemyGroup, x, y, 5500.00 * (Pow(1.5, I2R(gInt))), udg_B_EnemyUnitN)
		
		-- call BJDebugMsg("Кол-во доступных врагов"+I2S(Counter))
		-- Блок отдачи приказа
		u2 = BlzGroupUnitAt(gEnemyGroup, GetRandomInt(0, Counter - 1))
		if u2 ~= nil then
			
			-- call BJDebugMsg("Выбранный Враг "+GetUnitName(u2))
			x2 = GetUnitX(u2)
			y2 = GetUnitY(u2)
			u2 = nil
			
			LazyCount = 0
			CheckPlayer = GetOwningPlayer(ChosenUnit)
			GroupEnumUnitsInRange(gAllyGroup, x, y, (2000 * AiRadius) / 5, B_LazyN)
			gSubGroupCounter = 0
			GroupClear(gSubGroup)
			
			while true do
				u2 = FirstOfGroup(gAllyGroup)
				
				if u2 == nil then
					GroupPointOrder(gSubGroup, "attack", x2, y2)
					GroupClear(gSubGroup)
					gSubGroupCounter = 0
					if true then break end
				end
				GroupRemoveUnit(gAllyGroup, u2)
				
				
				GroupAddUnit(gSubGroup, u2)
				gSubGroupCounter = gSubGroupCounter + 1
				if gSubGroupCounter >= 12 then
					GroupPointOrder(gSubGroup, "attack", x2, y2)
					GroupClear(gSubGroup)
					gSubGroupCounter = 0
				end
			end
			
			gInt = 11
		else
			gInt = gInt + 1
		end
		
		if gInt > 10 then break end
		
		
	end
	
	-- call BJDebugMsg("------------------------- ")
	
	ChosenUnit = nil
	u2 = nil
	
end
