-- ***************************************************************************
-- *  GoToWater
---@param pi integer
---@param u unit
---@param x real
---@param y real
---@return boolean
function GoToWaterPoint(pi, u, x, y)
	
	if Random(1, 10) and LoadInteger(AiData, pi, StringHash("NumberPorts")) < 8 then
		if RectContainsCoords(gg_rct_EastenKingdoms, x, y) then
			gInt = GetRandomInt(1, 4)
			if gInt == 1 then
				IssuePointOrder(u, "move", 30150, -3454)
			elseif gInt == 2 then
				IssuePointOrder(u, "move", 25504, -16284)
			elseif gInt == 3 then
				IssuePointOrder(u, "move", 19258, 5665)
			elseif gInt == 4 then
				IssuePointOrder(u, "move", 10979, 10501)
			end
		elseif RectContainsCoords(gg_rct_Kalim, x, y) then
			gInt = GetRandomInt(1, 4)
			if gInt == 1 then
				IssuePointOrder(u, "move", -28610, 16300)
			elseif gInt == 2 then
				IssuePointOrder(u, "move", -15796, -10105)
			elseif gInt == 3 then
				IssuePointOrder(u, "move", -12405, 96678)
			elseif gInt == 4 then
				IssuePointOrder(u, "move", -27443, 11058)
			end
		elseif RectContainsCoords(gg_rct_Nord, x, y) then
			gInt = GetRandomInt(1, 4)
			if gInt == 1 then
				IssuePointOrder(u, "move", -4711, 20912)
			elseif gInt == 2 then
				IssuePointOrder(u, "move", 8753, 22230)
			elseif gInt == 3 then
				IssuePointOrder(u, "move", 1273, 20088)
			elseif gInt == 4 then
				IssuePointOrder(u, "move", -15652, 21381)
			end
		elseif RectContainsCoords(gg_rct_BrokenIsles, x, y) then
			gInt = GetRandomInt(1, 2)
			if gInt == 1 then
				IssuePointOrder(u, "move", 2500, 12654)
			else
				IssuePointOrder(u, "move", 4121, 621)
			end
		elseif RectContainsCoords(gg_rct_Pandaria, x, y) then
			gInt = GetRandomInt(1, 2)
			if gInt == 1 then
				IssuePointOrder(u, "move", -9460, -12451)
			else
				IssuePointOrder(u, "move", -3941, -22869)
			end
		end
		
		return true
	end
	return false
end
-- ***************************************************************************
-- *  TryToBuild
---@return nothing
function TryBuild()
	gUnit = TryBuild_u
	if gUnit == nil then
		return 
	end
	gPi = GetPlayerId(GetOwningPlayer(gUnit))
	gX = GetUnitX(gUnit)
	gY = GetUnitY(gUnit)
	
	
	-- call DisplayTimedTextFromPlayer( Player( 0x00 ), 0, 0, 4, "Вхожу в билд" )
	
	GroupAddUnit(udg_Ai_buildersT[gPi], gUnit)
	GroupRemoveUnit(udg_Ai_builders[gPi], gUnit)
	GroupRemoveUnit(udg_Ai_harvest[gPi], gUnit)
	
	
	-- Если в воде для верфи - то строй верфь c высоким шансом)
	if LoadInteger(AiData, gPi, StringHash("NumberPorts")) < 12 and ( not IsTerrainPathable(gX, gY, PATHING_TYPE_WALKABILITY) and RectContainsCoords(gg_rct_Outland, gX, gY) ~= true and RectContainsCoords(gg_rct_Azgel, gX, gY) ~= true) then
		
		
		if Random(1, 2) then
			
			gInt2 = 0
			
			while true do
				if gInt2 >= 5 then break end
				gInt2 = gInt2 + 1
				
				gX2 = gX + 200.00 * Cos(GetRandomReal(0.00, 360.00) * bj_DEGTORAD)
				gY2 = gY + 200.00 * Sin(GetRandomReal(0.00, 360.00) * bj_DEGTORAD)
				
				if  not (IsTerrainPathable(gX2, gY2, PATHING_TYPE_WALKABILITY) or IsTerrainPathable(gX2, gY2, PATHING_TYPE_FLOATABILITY) or RectContainsCoords(gg_rct_Outland, gX2, gY2)) then
					
					
					if AiDispatchWallBuild(gPi, gUnit, gX2, gY2) then
						return 
					end
				end
				
			end
		end
		
		
		-- Идти к точке где много воды
	elseif AiRaceUsesWaterPoint(gPi) and GoToWaterPoint(gPi, gUnit, gX, gY) then
		return 
	end
	
	-- Шанс перейти на новую локу
	if Random(1, 25) then
		gX = gX + AiBuildingRadius * 7 * Cos(GetRandomReal(0.00, 360.00) * bj_DEGTORAD)
		gY = gY + AiBuildingRadius * 7 * Sin(GetRandomReal(0.00, 360.00) * bj_DEGTORAD)
		IssuePointOrder(gUnit, "move", gX, gY)
		return 
	end
	
	
	--  Определение точки постройки 
	gX = gX + AiBuildingRadius * Cos(GetRandomReal(0.00, 360.00) * bj_DEGTORAD)
	gY = gY + AiBuildingRadius * Sin(GetRandomReal(0.00, 360.00) * bj_DEGTORAD)
	
	
	
	gInt = AiDispatchChooseBuild(gPi)
	
	IssueBuildOrderById(gUnit, gInt, gX, gY)
	
end
