---@return nothing
function CapTime()
	local u = udg_LocalUnit3
	SetUnitLifePercentBJ(u, 100)
	UnitAddAbility(u, FourCC('Avul'))
	RemoveAbilityTimed(u, FourCC('Avul'), 3)
