--===========================================================================
-- Trigger: DieDummy
--
-- Создает 3 шара которые кружат вокруг героя бесконечно пока он их не потратит или умрет
-- запуская их во врагов герой наносит им урон в 200 АОЕ и вешает противные бафы
-- Первый выпущенный шар вешает на врагов замедление
-- Второй выпущенный шар вешает на врагов хекс
-- Третий выпущенный шар вешает на врагов промахи
-- Не ставить перезарядку скила на 0 так как будут баги
--===========================================================================
function Trig_DieDummy_Func001Func002A()
    RemoveUnit(GetEnumUnit())
end
function Trig_DieDummy_Func001C()
    if ( not ( GetUnitTypeId(GetDyingUnit()) == FourCC('h0MK') ) ) then
        return false
    end
    return true
end
function Trig_DieDummy_Func002Func002A()
    RemoveUnit(GetEnumUnit())
end
function Trig_DieDummy_Func002C()
    if ( not ( GetUnitTypeId(GetDyingUnit()) == FourCC('h0MJ') ) ) then
        return false
    end
    return true
end
function Trig_DieDummy_Actions()
    if ( Trig_DieDummy_Func001C() ) then
        ForGroupBJ(GetUnitsOfTypeIdAll(FourCC('h0MK')), Trig_DieDummy_Func001Func002A)
    else
    end
    if ( Trig_DieDummy_Func002C() ) then
        ForGroupBJ(GetUnitsOfTypeIdAll(FourCC('h0MJ')), Trig_DieDummy_Func002Func002A)
    else
    end
end
