    UnitRemoveAbilityBJ(FourCC('A009'), GetEnumUnit())
end
function Trig_Sdelat_Flagman_Ot_Copy_Func019C()
    if ( not ( GetUnitTypeId(GetTriggerUnit()) == FourCC('h06W') ) ) then
        return false
    end
    return true
