function InitTrig_Remove_Unit_From_LoadedGroup()
    gg_trg_Remove_Unit_From_LoadedGroup=CreateTrigger()
    TriggerAddAction(gg_trg_Remove_Unit_From_LoadedGroup, Trig_Remove_Unit_From_LoadedGroup_Actions)
end
