    if ( not ( IsUnitInGroup(udg_TempUnit02, udg_TransportingGroup) == true ) ) then
        return false
    end
    return true
end
function Trig_TransportingUnitArray_Message_Actions()
    if ( Trig_TransportingUnitArray_Message_Func001C() ) then
