    if ( not ( udg_Portal_preventAllies[udg_Portal_INDEX_TARGET] == true ) ) then
        return false
    end
    if ( not ( GetOwningPlayer(GetTriggerUnit()) ~= GetOwningPlayer(GetOrderTargetUnit()) ) ) then
        return false
    end
    return true
end
