--===========================================================================
-- Trigger: F2 2
--===========================================================================
function Trig_F2_2_Conditions()
    return GetSpellAbilityId() == FourCC('A167')
end
function Trig_F2_2_Actions()
    local pi= GetPlayerId(GetOwningPlayer(GetTriggerUnit()))
    local g= CreateGroup()
    local g0= CreateGroup()
    local u
    local i= 0
    local loc= GetSpellTargetLoc()
    
    --set g = udg_F_Group[pi+1]
    GroupAddGroup(udg_F_Group[pi + 1], g)
    while true do
    
        u=FirstOfGroup(g)
        if u == nil then
            GroupPointOrderLoc(g0, "attack", loc)
            if true then break end
        end
             
        if i == 12 then
            GroupPointOrderLoc(g0, "attack", loc)
            i=0
            GroupClear(g0)
            
        else
        
        end
        i=i + 1
        GroupAddUnit(g0, u)
        GroupRemoveUnit(g, u)
        u=null
    end
    DestroyGroup(g)
    DestroyGroup(g0)
    g=null
    g0=null
    RemoveLocation(loc)
    loc=null
end
