--===========================================================================
function Trig_TrainW2_Conditions()
    return GetUnitAbilityLevel(GetTrainedUnit(), FourCC('w2a0')) > 0
end
function Trig_TrainW2_Actions()
    local u= GetTrainedUnit()
    local uh= GetHandleId(u)
    local p= GetOwningPlayer(u)
    local r
