    gg_trg_BoneDeal=CreateTrigger()
    TriggerRegisterAnyUnitEventBJ(gg_trg_BoneDeal, EVENT_PLAYER_UNIT_SPELL_EFFECT)
    TriggerAddCondition(gg_trg_BoneDeal, Condition(Trig_BoneDeal_Conditions))
