    TriggerRegisterAnyUnitEventBJ(gg_trg_Help, EVENT_PLAYER_UNIT_DAMAGED)
    TriggerAddCondition(gg_trg_Help, Condition(Trig_Help_Conditions))
    TriggerAddAction(gg_trg_Help, Trig_Help_Actions)
end
