--===========================================================================
-- Trigger: AK1T1
--===========================================================================
function Trig_AK1T1_Conditions()
    return GetUnitTypeId(GetTrainedUnit()) == FourCC('hfoo')
end
function AT1Count()
    local a = {}
    local i= 0
    local b= 0
    local pi= GetPlayerId(p)
    a[0]=0
    -- Штормград простой
    
    if GetPlayerTechCount(p, FourCC('R0H6'), true) < 1 then
        i=4
        --Stormwind common
        while true do
                a[0]=a[0] + 1
                a[a[0]]=FourCC('h0KD')
                b=b + 1
                if b >= i then break end
        end
    else
        --Stromwind blue
        i=4
        while true do
                a[0]=a[0] + 1
                a[a[0]]=FourCC('h0LW')
                b=b + 1
                if b >= i then break end
        end
    
    end
    
    --Лордеронец
    if GetPlayerTechCount(p, FourCC('R0HH'), true) < 1 then
        i=1
        b=1
        
        -- интеграция лордеронцев
        if GetPlayerTechCount(p, FourCC('R0HV'), true) > 1 then
            i=i + 2
        end
        
        while true do
            a[0]=a[0] + 1
            a[a[0]]=FourCC('h0KR')
            
            b=b + 1
            if b >= i then break end
        end
    end
    --Stromgarge
    if GetPlayerTechCount(p, FourCC('R0HJ'), true) > 0 then
        i=3
        b=1
        
      
        
        while true do
            a[0]=a[0] + 1
            a[a[0]]=FourCC('h0M9')
            
            b=b + 1
            if b >= i then break end
        end
    end
    
    --Long Containment
    SaveInteger(CommonHash, pi, StringHash("AT1_0"), a[0])
    i=1
    while true do
        
        
        SaveIntegerIfPresent(CommonHash, pi, StringHash("AT1") + i, a[i])
        i=i + 1
        
        if i > a[0] then break end
    end
    
    
    
    
end
function Trig_AK1T1_Actions()
    local a = {}
    local i= 0
    local b= 0
    local p= GetOwningPlayer(GetTriggerUnit())
    local l= GetUnitRallyPoint(GetTriggerUnit())
    local u
    local pi= GetPlayerId(p)
    
    
    i=LoadInteger(CommonHash, pi, StringHash("AT1_0"))
    i=GetRandomInt(1, i)
    b=LoadInteger(CommonHash, pi, ( StringHash("AT1") + i ))
    
    u=ReplaceUnit(GetTrainedUnit() , b , bj_UNIT_STATE_METHOD_RELATIVE)
    
   
    --call UnitAddAbility(u,'OR00')
    --call SetUnitAbilityLevel(u,'OR00',35+udg_HordeLandPrice[pi])
    
    
     
    UnitAddAbility(u, FourCC('A17P'))
    IssuePointOrderLoc(u, "attack", l)
    RemoveLocation(l)
    p=null
    u=null
end
