function Trig_BegEvery_Func001C()
    if ( ( GetResearched() == FourCC('R0HS') ) ) then
        return true
    end
    if ( ( GetResearched() == FourCC('R0HR') ) ) then
        return true
    end
    if ( ( GetResearched() == FourCC('R0HQ') ) ) then
        return true
    end
    return false
end
