    if ( not Trig_BegEvery_Func001C() ) then
        return false
    end
    return true
end
function Trig_BegEvery_Actions()
    SetPlayerTechMaxAllowedSwap(FourCC('R0GX'), 0, GetOwningPlayer(GetTriggerUnit()))
end
