        BlzStartUnitAbilityCooldown(u, FourCC('A13M'), 12)
        BlzStartUnitAbilityCooldown(u, FourCC('A13K'), 45)
        GroupRemoveUnit(g, u)
        u=null
    end
    
    
    DestroyGroup(g)
    g=null
    p=null
    u=null
end
