--===========================================================================
function Trig_K1T2_Conditions()
    return GetUnitTypeId(GetTrainedUnit()) == FourCC('o01N')
end
function T2Count()
    local a = {}
    local i= 0
    local b= 0
    local pi= GetPlayerId(p)
    
    --1 юнит
    a[0]=0
    
    b=0
    i=2
    while true do --Орк
            a[0]=a[0] + 1
            a[a[0]]=FourCC('o01Q')
            b=b + 1
            if b >= i then break end
    end
    
    b=0
    i=1
    while true do --Огр
            a[0]=a[0] + 1
            a[a[0]]=FourCC('o01O')
            b=b + 1
            if b >= i then break end
    end
    
    
    if GetPlayerTechCount(p, FourCC('R0EE'), true) == 1 and GetPlayerTechCount(p, FourCC('R0E9'), true) ~= 1 then
        b=0
        i=1
        while true do --Pandaren
                a[0]=a[0] + 1
                a[a[0]]=FourCC('o02S')
                b=b + 1
                if b >= i then break end
        end
    end
    
    --Long Containment
    SaveInteger(CommonHash, pi, StringHash("T2_0"), a[0])
    i=1
    while true do
        
        
        SaveIntegerIfPresent(CommonHash, pi, StringHash("T2") + i, a[i])
        i=i + 1
