    SetPlayerTechMaxAllowedSwap(FourCC('R09L'), 2, p) -- Его грейд
    SetPlayerTechMaxAllowedSwap(FourCC('o04T'), - 1, p) -- Golem
    SetPlayerTechMaxAllowedSwap(FourCC('R09P'), 2, p) -- Golem grade
    
