    gg_trg_Spell_E_Dvij=CreateTrigger()
    TriggerRegisterTimerExpireEventBJ(gg_trg_Spell_E_Dvij, udg_Timer_E_Glaz)
    TriggerAddAction(gg_trg_Spell_E_Dvij, Trig_Spell_E_Dvij_Actions)
