    if ( not ( S2I(SubStringBJ(GetEventPlayerChatString(), 4, 5)) >= 1 ) ) then
        return false
    end
    if ( not ( S2I(SubStringBJ(GetEventPlayerChatString(), 4, 5)) <= 24 ) ) then
        return false
    end
    return true
