function Trig_P1_Vs_P2_P3_P4_Actions()
    SetPlayerAllianceStateBJ(Player(2), Player(1), bj_ALLIANCE_ALLIED_VISION)
    SetPlayerAllianceStateBJ(Player(3), Player(1), bj_ALLIANCE_ALLIED_VISION)
