function PlayerNavy()
    local l__gGroup= CreateGroup()
    local p= null
    local u
    local id
    local i
    local i2
    --Локалки
    
    --Каждый отдельный игрок
    --Узнаю номер игрока
    
    if CountPlayersInForceBJ(udg_BotsActiveN) == 0 then
        PauseTimer(udg_PlayerGet4)
        ResumeTimer(udg_TimerSmall4)
