        if udg_Octhet then
            DisplayTimedTextFromPlayer(Player(0), 0, 0, 4, "")
        end
    else
        
        p=ForcePickRandomPlayer(udg_BotsActiveN)
        local pi_navy = GetPlayerId(p)
        if not LoadBoolean(AiData, pi_navy, StringHash("Log_PlayerNavy")) then
